def p = { String k -> binding.hasVariable(k) ? binding.getVariable(k) : null }
def s = { String k -> (p(k) ?: '').toString() }
def code = 'DOC-' + System.currentTimeMillis()
def name = s('file_name')
def ext = name.contains('.') ? name.substring(name.lastIndexOf('.') + 1).toLowerCase() : 'pdf'
def now = new java.sql.Timestamp(System.currentTimeMillis()).toString()
def payload = [doc_code: code, title: (s('title') ?: name), entity_code: s('entity_code'), file_name: name, mime_type: s('mime_type'),
  file_source: s('file_source'), file_url: s('file_url'), uploaded_by: s('uploaded_by'), uploaded_at: now, status: 'ANALYSING']
def files = [[fileObject: [source: s('file_source'), sourceType: 'CLOUD_STORAGE', name: name, fileType: ext], mimeType: (s('mime_type') ?: 'application/pdf')]]
return [code: code, payload: payload, files: files]

def p = { String k -> binding.hasVariable(k) ? binding.getVariable(k) : null }
def raw = (p('output') ?: '').toString().trim()
if (raw.startsWith('```')) { raw = raw.replaceAll('^```[a-zA-Z]*', '').replaceAll('```$', '').trim() }
def j = null
try { j = new groovy.json.JsonSlurper().parseText(raw) } catch (e) { j = null }
def J = { v -> groovy.json.JsonOutput.toJson(v ?: []) }
def now = new java.sql.Timestamp(System.currentTimeMillis()).toString()
def f = [:]
if (j instanceof Map) {
  f.status = 'ANALYSED'; f.doc_type = (j.doc_type ?: 'other').toString(); f.summary = (j.summary ?: '').toString()
  f.key_points_json = J(j.key_points); f.metrics_json = J(j.metrics); f.risks_json = J(j.risks); f.recommendations_json = J(j.recommendations)
  f.entities_json = J([entities: j.entities_mentioned ?: [], regions: j.regions_mentioned ?: []]); f.sentiment = (j.sentiment ?: 'neutral').toString()
  def t = (j.full_text ?: '').toString(); f.extracted_text = t.length() > 6000 ? t.substring(0, 6000) : t; f.error = ''
} else {
  f.status = 'FAILED'; f.error = ('Could not read the analysis. status=' + (p('status') ?: '') + ' ' + (p('errMsg') ?: '') + ' raw=' + raw.take(500)).toString()
}
f.analysed_at = now
return [updates: [[id: p('code').toString(), updateFields: f.collect { k, v -> [fieldName: k, actionType: 'SET', setValue: v] }]], status: f.status, summary: (f.summary ?: f.error)]
